import{_ as t,o as a,c as d,a5 as o}from"./chunks/framework.BqnnR8ku.js";const g=JSON.parse('{"title":"流水线与原理","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/pipeline.md","filePath":"zh/guide/pipeline.md"}'),s={name:"zh/guide/pipeline.md"};function c(i,e,r,n,l,h){return a(),d("div",null,[...e[0]||(e[0]=[o(`<h1 id="流水线与原理" tabindex="-1">流水线与原理 <a class="header-anchor" href="#流水线与原理" aria-label="Permalink to &quot;流水线与原理&quot;">​</a></h1><p>本页说明翻译 <strong>如何执行</strong>：多轮计划、内容保护、响应修复、批量与重试、质量裁决等。偏「为什么 / 内部怎么走」。</p><div class="tip custom-block"><p class="custom-block-title">查字段与界面步骤</p><ul><li>界面怎么配：<a href="/LinguaFlow/zh/guide/translation-config.html">翻译配置 · 使用</a></li><li>字段与默认值：<a href="/LinguaFlow/zh/guide/translation-config-reference.html">翻译配置 · 参考</a></li><li>CLI 配置文件：<a href="/LinguaFlow/zh/guide/configuration.html">配置文件与环境变量</a></li></ul></div><h2 id="作业如何跑起来" tabindex="-1">作业如何跑起来 <a class="header-anchor" href="#作业如何跑起来" aria-label="Permalink to &quot;作业如何跑起来&quot;">​</a></h2><p>创建翻译作业时，系统会 <strong>固化</strong> 当前执行计划快照，后台 Worker 按资源依次处理。</p><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart TD</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  Start([创建作业]) --&gt; Res[每个资源]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  Res --&gt; Next{下一轮次}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  Next --&gt;|extract| Ex[抽术语 → 写术语表]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  Next --&gt;|translate| Tr[翻译段落]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  Next --&gt;|correct| Co[本地改写译文，消除安全问题]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  Next --&gt;|adjudicate| Ad[复核规则质检问题]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  Next --&gt;|revise| Re[LLM 定点修订译文]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  Next --&gt;|semantic_qa| Sq[LLM 语义扫描]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  Next --&gt;|完成| Done([结束])</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  Ex --&gt; Next</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  Tr --&gt; Next</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  Co --&gt; Next</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  Ad --&gt; Next</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  Re --&gt; Next</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  Sq --&gt; Next</span></span></code></pre></div><p><strong>翻译轮次内部（简要）：</strong></p><ol><li>内容保护（占位符替换）</li><li>组装上下文 → 调用 AI</li><li>还原占位符 / 后处理 / 可选 Ruby 还原</li><li>规则质检写回段落（18 项 per-batch checker + 1 项文档级 + 注音守恒码）</li></ol><p>可选：执行配置中的 <strong>内联术语自举</strong> 会在翻译响应中一并抽术语。语义质检产生的 <code>warning</code> 级问题通过 <code>span</code> 精确定位到译文片段。可选的 <code>revise</code> 轮按段落上 <code>pending</code> 语义 issue 对现有译文做定点最小修订。</p><p>推荐轮次顺序：<code>extract</code>（可选）→ <code>translate</code>（可多轮）→ <code>correct</code>（可选）→ <code>adjudicate</code>（可选）→ <code>revise</code>（可选）→ <code>semantic_qa</code>（可选）。</p><hr><h2 id="多轮翻译-级联回退" tabindex="-1">多轮翻译：级联回退 <a class="header-anchor" href="#多轮翻译-级联回退" aria-label="Permalink to &quot;多轮翻译：级联回退&quot;">​</a></h2><p>多个 <strong><code>translate</code> 轮次</strong> 不是「润色流水线」，而是 <strong>失败回退</strong>：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Round 1：尝试全部待译段落</span></span>
<span class="line"><span>  ├─ 成功 → 写入，该段结束</span></span>
<span class="line"><span>  └─ 失败 → 交给 Round 2</span></span>
<span class="line"><span>Round 2：只处理 Round 1 失败的段落</span></span>
<span class="line"><span>  └─ …</span></span></code></pre></div><p><strong>典型用途：</strong> 主模型失败换备用模型；第二轮更小批次 / 更低并发提高成功率。</p><p>提取轮次在翻译前写术语；裁决轮次在规则质检之后做降噪。配置入口见 <a href="/LinguaFlow/zh/guide/translation-config.html#执行计划">翻译配置 · 使用 · 执行计划</a>。</p><hr><h2 id="批量与并发" tabindex="-1">批量与并发 <a class="header-anchor" href="#批量与并发" aria-label="Permalink to &quot;批量与并发&quot;">​</a></h2><p>每轮按 <code>batch_size</code>（待译段落数）与/或 <code>max_words_per_batch</code>（字词数）组批，Worker 池并发请求。</p><ul><li>CJK 常按字符计词；非 CJK 常按空白分词</li><li><strong><code>batch_size</code> 只数待译段</strong>，不把上下文段算进去；<code>max_words_per_batch</code> 则把上下文段的字数也计入预算（避免上下文把整批塞满）。纯行数模式（二者与 <code>context.max_chars</code> 均为 0）时上下文体积不受约束</li><li>批次会带上上下文窗口，保证连贯；组批时还会<strong>预估上下文段的词数并扣减预算</strong>，避免因上下文膨胀导致批次超限</li><li><strong>失败降级（池化缩批）</strong>：<code>fallback_shrink</code> 是翻译轮的必填系数（合法域 (0, 1]）——<code>1.0</code> 启用多池同尺寸重切，<code>(0,1)</code> 启用多池缩批，失败段按更小的批次约束重试，直到最小 1 段</li><li>仍失败的段落可进入下一翻译轮次</li></ul><h3 id="池化缩批怎么走" tabindex="-1">池化缩批怎么走 <a class="header-anchor" href="#池化缩批怎么走" aria-label="Permalink to &quot;池化缩批怎么走&quot;">​</a></h3><p><code>fallback_shrink</code> 是池缩比系数（必填，合法域 (0, 1]）。各池串行执行，前一个池里失败的批次会重新切批、进入下一个更小的池；<code>1.0</code> 时各池同尺寸（只重切不缩小），<code>(0,1)</code> 时每池按系数缩小：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>池 0：批次约束 = 原始 batch_size（或 max_words_per_batch）</span></span>
<span class="line"><span>  ├─ 成功 → 写入，该段结束</span></span>
<span class="line"><span>  └─ 失败 → 交给池 1</span></span>
<span class="line"><span>池 1：批次约束 = floor(原始 × shrink)        （shrink=1.0 时与池 0 相同）</span></span>
<span class="line"><span>  └─ 失败 → 交给池 2</span></span>
<span class="line"><span>池 2：批次约束 = floor(原始 × shrink²)       （shrink=1.0 时仍相同）</span></span>
<span class="line"><span>  └─ … 直到最小 1 段</span></span></code></pre></div><p><strong>关键参数</strong>：</p><ul><li><strong>池数量 = <code>retry.max_attempts + 1</code></strong>——<code>max_attempts</code> 决定池深度，每池在途重试预算内部封顶 <code>min(max_attempts, 3)</code>、不单独暴露</li><li>最坏情况下单段调用次数 ≈ <code>(max_attempts + 1)²</code>（每池重试 × 池数）</li><li>各池之间是<strong>串行</strong>的，只有前一池失败的段才会进下一池；成功段不会被重复处理</li></ul><p>工作区作业时间线会以「池级事件」卡片展示当前所处池、批次数与待处理数，方便观察缩批进度。</p><div class="tip custom-block"><p class="custom-block-title">不缩只重切用 1.0</p><p><code>fallback_shrink = 1.0</code> 时多池批次约束相同，相当于「失败段重新按原批次大小再试一遍」而非缩小批次；适合响应稳定、但偶发解析失败需要重切的后端。<code>0</code> 非法（会被后端拒绝）；确需单池不重切，请减少 <code>retry.max_attempts</code>。</p></div><p>字段表见 <a href="/LinguaFlow/zh/guide/translation-config-reference.html#translate">翻译配置 · 参考 · translate</a>；重试参数见 <a href="/LinguaFlow/zh/guide/translation-config-reference.html#重试-retry">翻译配置 · 参考 · 重试</a>。</p><hr><h2 id="内容保护" tabindex="-1">内容保护 <a class="header-anchor" href="#内容保护" aria-label="Permalink to &quot;内容保护&quot;">​</a></h2><p>翻译前将代码、链接、占位符、HTML 标签等换成 <code>__LF_000001__</code> 形式（固定宽度编号），译后还原。</p><ul><li>默认规则：<code>code</code> / <code>link</code> / <code>placeholder</code> / <code>xml</code></li><li>相邻占位符可能合并，减少对模型的干扰</li><li>模型应 <strong>原样保留</strong> 占位符字符串</li></ul><p>规则列表见 <a href="/LinguaFlow/zh/guide/translation-config-reference.html#内容保护-protect">翻译配置 · 参考 · protect</a>。</p><hr><h2 id="上下文窗口" tabindex="-1">上下文窗口 <a class="header-anchor" href="#上下文窗口" aria-label="Permalink to &quot;上下文窗口&quot;">​</a></h2><p>为当前段附带前后各 N 段作 <strong>只读参考</strong>（不译）。</p><ul><li>优先用保护前的原文，便于模型阅读</li><li><code>max_chars</code> &gt; 0 时按 rune 计数截断并补省略号（在句末附近截断，保留可读性）</li><li>跳过空段、纯占位符、装饰分隔线</li></ul><h3 id="与批次预算的关系" tabindex="-1">与批次预算的关系 <a class="header-anchor" href="#与批次预算的关系" aria-label="Permalink to &quot;与批次预算的关系&quot;">​</a></h3><p>上下文段会<strong>占用 <code>max_words_per_batch</code> 的字词预算</strong>（但不计入 <code>batch_size</code> 的段落数）。为防止「上下文比待译正文还长」把整批顶到超限，组批时会先<strong>预估上下文段的词数</strong>并从预算里扣减，再决定一个批次能装多少待译段。预估逻辑与实际上下文选段一致，避免「预估小、实际大」的偏差。</p><p>这意味着：开大上下文窗口（<code>before</code>/<code>after</code> 较大）时，每个批次的待译段数会自动变少，无需手动调小 <code>batch_size</code>。<code>batch_size</code> 与 <code>max_words_per_batch</code> 都为 0 的纯行数模式下上下文体积不受约束，仅在确信上下文很短时使用。</p><p>参数见 <a href="/LinguaFlow/zh/guide/translation-config-reference.html#上下文-context">翻译配置 · 参考 · context</a>。</p><hr><h2 id="响应修复" tabindex="-1">响应修复 <a class="header-anchor" href="#响应修复" aria-label="Permalink to &quot;响应修复&quot;">​</a></h2><p>模型输出不总是合法 JSON。修复链大致包括：</p><table tabindex="0"><thead><tr><th>级别</th><th>内容</th></tr></thead><tbody><tr><td>结构</td><td>BOM/控制字符、括号、尾逗号等</td></tr><tr><td>别名</td><td><code>translation</code> / <code>result</code> 等映射到 <code>translations</code></td></tr><tr><td>占位符</td><td>大小写/下划线变体归一</td></tr><tr><td>提示升级</td><td>附加反例 reminder 再请求一次</td></tr></tbody></table><p>修复层只负责把响应解析成<strong>可解析的翻译 ID 列表</strong>——即「哪些段拿到了译文」。个别段没回（部分段缺失）<strong>不再在修复配置里单独开关</strong>，而是直接交给 <a href="#批量与并发">池化缩批重试</a>：缺失段进入更小的池按更小批次重译，由上层引擎统一管理。这样把「解析」与「重试」两个职责解耦，修复配置也更简洁。</p><p>纯文本模式下还有去围栏、解析 <code>[glossary]</code> / <code>[ruby]</code> 等逻辑。开关见 <a href="/LinguaFlow/zh/guide/translation-config-reference.html#响应修复-repair">翻译配置 · 参考 · repair</a>。</p><hr><h2 id="术语提取-bootstrap" tabindex="-1">术语提取（Bootstrap） <a class="header-anchor" href="#术语提取-bootstrap" aria-label="Permalink to &quot;术语提取（Bootstrap）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>模式</th><th>机制</th></tr></thead><tbody><tr><td><strong>独立提取</strong>（计划 <code>extract</code> 或 pre）</td><td>译前单独调用，写术语表，后续翻译轮次共享</td></tr><tr><td><strong>内联</strong>（执行配置 bootstrap）</td><td>翻译响应中顺带返回术语，省一次调用</td></tr></tbody></table><p>内联冲突策略：</p><table tabindex="0"><thead><tr><th>策略</th><th>行为</th></tr></thead><tbody><tr><td><code>rewrite-local</code>（默认）</td><td>冲突时以术语表权威译法改写本批译文</td></tr><tr><td><code>off</code></td><td>先到先得，文档内可能不一致</td></tr></tbody></table><p>产品操作见 <a href="/LinguaFlow/zh/guide/glossary.html">术语表管理</a>；字段见 <a href="/LinguaFlow/zh/guide/translation-config-reference.html#术语自举-bootstrap">翻译配置 · 参考</a>。</p><hr><h2 id="规则质检与-ai-质量裁决" tabindex="-1">规则质检与 AI 质量裁决 <a class="header-anchor" href="#规则质检与-ai-质量裁决" aria-label="Permalink to &quot;规则质检与 AI 质量裁决&quot;">​</a></h2><h3 id="规则质检" tabindex="-1">规则质检 <a class="header-anchor" href="#规则质检" aria-label="Permalink to &quot;规则质检&quot;">​</a></h3><p>翻译轮次内由 QA 引擎同步跑规则检查并写回段落。共 18 项 per-batch checker（可在执行配置 <code>qa.checks</code> 中按名选择性启用）+ 1 项文档级 <code>duplicate_source_divergence</code>（跨段比对，不可在 <code>qa.checks</code> 中关闭）；另由翻译轮的注音守恒逻辑产出 <code>ruby_restore_incomplete</code> / <code>ruby_tag_loss</code> 两个守恒码：</p><table tabindex="0"><thead><tr><th>code</th><th>含义</th><th>可否 AI 裁决</th></tr></thead><tbody><tr><td><code>length_ratio</code></td><td>过短/过长</td><td>✅ 软规则</td></tr><tr><td><code>duplicate</code></td><td>相邻译文完全相同</td><td>❌ 硬规则</td></tr><tr><td><code>duplicate_source_divergence</code></td><td>文档级同源异译</td><td>❌ 文档级</td></tr><tr><td><code>untranslated</code></td><td>译文=原文</td><td>❌ 硬规则</td></tr><tr><td><code>source_residual</code></td><td>译文夹源语脚本</td><td>✅ 软规则</td></tr><tr><td><code>punctuation_pairing</code></td><td>标点配对不平衡</td><td>❌ 硬规则</td></tr><tr><td><code>punctuation_missing</code></td><td>源文整类包裹标点在译文中完全缺失</td><td>❌ 硬规则</td></tr><tr><td><code>punctuation_surplus</code></td><td>译文多出源文所无的成对包裹标点</td><td>✅ 软规则</td></tr><tr><td><code>punctuation_wrap_loss</code></td><td>源文整段被成对引号包裹，译文首尾丢失外层引号</td><td>✅ 软规则</td></tr><tr><td><code>ruby_restore_incomplete</code></td><td>翻译轮该段应还原的 <code>&lt;ruby&gt;</code> 注音只还原了部分</td><td>❌ 软规则</td></tr><tr><td><code>ruby_tag_loss</code></td><td>人工编辑把原本含注音的译文改到一条注音不剩</td><td>❌ 软规则</td></tr><tr><td><code>whitespace_irregular</code></td><td>零宽/NBSP/制表符等异常空白</td><td>❌ 硬规则</td></tr><tr><td><code>repeated_space</code></td><td>连续空格 / CJK 间空格</td><td>❌ 硬规则</td></tr><tr><td><code>width_mix</code></td><td>全/半角混用（仅检零歧义安全集：CJK 译文的 <code>! ? , ; : ( ) [ ]</code> 半角标点与拉丁译文的全角字符 FF01-FF5E，数字写法如 <code>1,000</code>/<code>12:30</code>/<code>5!</code> 豁免）</td><td>❌ 硬规则</td></tr><tr><td><code>number_mismatch</code></td><td>阿拉伯数字集合不一致（全角数字归一化后比对）</td><td>❌ 硬规则</td></tr><tr><td><code>url_email_mismatch</code></td><td>URL/邮箱集合不一致</td><td>❌ 硬规则</td></tr><tr><td><code>subtitle_line_count</code></td><td>字幕行数不一致</td><td>❌ 硬规则</td></tr><tr><td><code>forbidden_term</code></td><td>命中禁译词条却仍出现在译文</td><td>❌ 硬规则</td></tr><tr><td><code>term_inconsistency</code></td><td>命中强制词条但译文未用 target</td><td>❌ 硬规则</td></tr><tr><td><code>leftover_placeholder</code></td><td>译文残留 <code>__LF_*</code> 占位符</td><td>❌ 硬规则</td></tr><tr><td><code>xml_tag_mismatch</code></td><td>XML 标签集合不一致</td><td>❌ 硬规则</td></tr></tbody></table><p>源语残留按 Unicode 脚本与语言对分档（独立脚本偏严；共汉字语言对有不同策略）。源语言为 <code>auto</code> 时残留检测不生效。规则与可裁决性等细节见 <a href="/LinguaFlow/zh/guide/review.html#质量检测">翻译审校 · 质量检测</a>。</p><h4 id="保护区-不被原文结构干扰" tabindex="-1">保护区：不被原文结构干扰 <a class="header-anchor" href="#保护区-不被原文结构干扰" aria-label="Permalink to &quot;保护区：不被原文结构干扰&quot;">​</a></h4><p>很多 checker（标点配对、空白、全/半角混用等）盯着译文里的字符细节。可原文里本来就带着 HTML 标签、URL 等结构（它们在译文里已被还原回来），如果直接在还原后的整串上跑 checker，这些结构里的英文标点、空格会被当成译文问题误报。</p><p>LinguaFlow 用<strong>保护区</strong>解决：QA 引擎拿到内容保护阶段记录的占位符映射，在译文里把属于原文结构的区段标出来，checker 在这些区段上<strong>跳过检测</strong>，但保护区之外的真问题仍照常定位上报。效果是——HTML 标签、链接等原文结构不再制造噪声 issue，而译文人手写错的标点、空白依旧被抓。</p><div class="tip custom-block"><p class="custom-block-title">XML 标签与 Ruby 注音</p><p>通用的 <code>xml_tag_mismatch</code> 比对源/译 XML 标签多重集时，会<strong>排除 <code>&lt;ruby&gt;</code>/<code>&lt;rt&gt;</code>/<code>&lt;rp&gt;</code>/<code>&lt;rb&gt;</code> 注音标签族</strong>——这些标签的守恒由 Ruby 还原子系统独立负责（<code>preserve_kinds</code> 过滤会合法地从译文移除它们），在通用标签比对里排除能避免配置耦合产生的误报。</p></div><h3 id="质量裁决-adjudicate" tabindex="-1">质量裁决（<code>adjudicate</code>） <a class="header-anchor" href="#质量裁决-adjudicate" aria-label="Permalink to &quot;质量裁决（\`adjudicate\`）&quot;">​</a></h3><p>对软规则问题逐条问 AI：<code>real</code> 保留 / <code>false_positive</code> 标记为 <code>dismissed</code>（保留记录、后续轮次跳过）。</p><ol><li>只处理已译/已改且带可裁决 code（<code>source_residual</code> / <code>length_ratio</code> / <code>punctuation_surplus</code>）的段落</li><li>分批调用 <strong>内置</strong> 裁决提示词</li><li>解析失败时 <strong>保留原问题</strong>，不清空</li></ol><p><strong>建议：</strong> 放在翻译轮次之后；专有名词多的文档优先开 <code>source_residual</code>。不配 <code>adjudicate_codes</code> 时默认裁决 <code>source_residual</code> 与 <code>punctuation_surplus</code>；<code>length_ratio</code> 需显式勾选。配置见 <a href="/LinguaFlow/zh/guide/translation-config.html#进阶组合">翻译配置 · 使用</a>；协议细节见 <a href="/LinguaFlow/zh/guide/translation-config-reference.html#adjudicate">翻译配置 · 参考 · adjudicate</a>。</p><h3 id="本地改写-correct" tabindex="-1">本地改写（<code>correct</code>） <a class="header-anchor" href="#本地改写-correct" aria-label="Permalink to &quot;本地改写（\`correct\`）&quot;">​</a></h3><p>纯本地的机械修正轮次，<strong>不调 LLM、无后端、无重试</strong>。消费规则质检已报出的安全问题，按 <code>rules</code> 顺序对译文做确定性改写：</p><ol><li>扫描 <code>translated</code> / <code>edited</code> 且译文非空的段——按文档自动扫描时只处理 <code>Translate=true</code> 的段（用户未选中的段不会被机械纠错）；跨轮增量会排除已被前一同模式轮解决的段</li><li>规则按配置顺序执行，<strong>首个生效改写即停</strong>（不叠加）；已被裁决为 <code>dismissed</code> 的问题不触发改写</li><li><strong>幂等校验</strong>：改写后用同一 checker（规则声明 <code>ResolvedCodes</code> 的并集）重跑——若该 issue code 仍报出，则<strong>回滚译文、保留原问题</strong>，避免把「没修好」伪装成「已修好」。已被 <code>dismissed</code> 的问题指纹不计入校验、其裁决记录保留，避免把用户判定为「不是问题」的项又改回去</li></ol><p>首发规则 <code>punctuation_missing_wrap</code>：当源文是单段配对引号包裹（<code>「…」</code> / <code>“…”</code> / <code>『…』</code> 等）且译文丢失该引号时，自动在译文首尾补回对应开闭引号；多段包裹、译文已有该引号、非配对引号等不安全场景一律不处理。该规则只对仍处于 <code>pending</code> 的问题触发，已 <code>dismissed</code> 的不再修复。</p><p>另有 <code>punctuation_wrap_loss_wrap</code>（补回整段丢失的外层引号）与 <code>width_mix_normalize</code>（把 <code>width_mix</code> 报出的零歧义全/半角混用按目标语方向归一：CJK 转全角、拉丁转半角，数字写法如 <code>1,000</code>/<code>12:30</code>/<code>5!</code> 豁免）。执行计划编辑器会列出全部已知规则，模板未保存过的规则以关闭状态出现，可自行开启。规则清单与行为见 <a href="/LinguaFlow/zh/guide/translation-config-reference.html#correct">翻译配置 · 参考 · correct</a>。</p><div class="tip custom-block"><p class="custom-block-title">修复、修订、裁决、语义质检各管一段</p><ul><li><code>correct</code> / <code>revise</code> 都<strong>改写译文</strong>以消除已报出的问题：<code>correct</code> 纯本地机械修复高频安全问题、不调 LLM；<code>revise</code> 调 LLM 按语义 issue 做定点最小修订。两者都沿用幂等契约——改写后重跑确定性 QA 验证，改不掉就回滚</li><li><code>adjudicate</code> 只判断已有软规则问题<strong>保留 / 标记为 <code>dismissed</code></strong>、不改译文</li><li><code>semantic_qa</code> <strong>新增</strong>语义类问题</li></ul><p>四者互补，可叠加放在翻译轮次之后。</p></div><p>配置字段见 <a href="/LinguaFlow/zh/guide/translation-config-reference.html#correct">翻译配置 · 参考 · correct</a>；可修复的 issue code 与 <a href="/LinguaFlow/zh/guide/review.html#质量检测">翻译审校 · 质量检测</a> 对应。</p><h3 id="llm-修订-revise" tabindex="-1">LLM 修订（<code>revise</code>） <a class="header-anchor" href="#llm-修订-revise" aria-label="Permalink to &quot;LLM 修订（\`revise\`）&quot;">​</a></h3><p>以段落上 <code>pending</code>（未裁决 <code>dismissed</code>）的语义 issue 为修复目标，调 LLM 对<strong>现有译文</strong>做最小改动的定点修订（不重译原文），系统提示词内置、不可覆盖。与 <code>correct</code> 共享写回契约：</p><ol><li>仅处理 <code>translated</code> / <code>edited</code> 且译文非空的段，按 <code>segment_scope</code>（<code>with_issues</code> / <code>with_issue_codes</code>）扫描——只取段落上 <code>pending</code> 的语义 issue 作修复目标</li><li><code>issue_codes</code> 仅取 8 个语义白名单（<code>calque</code> / <code>term_fidelity</code> / <code>naturalness</code> / <code>mistranslation</code> / <code>omission</code> / <code>addition</code> / <code>grammar</code> / <code>register</code>），与段落实有 <code>pending</code> 语义 issue 取交集，交集为空的段不进入修订</li><li>protect/ruby 及引擎级策略（repair/QA/glossary）经计划级 <code>profile_id</code> 贯穿，无需依赖计划内 translate 轮</li><li>写回遵循 correct 先例：改写译文与 issues、不改段落状态、CAS 保护；<strong>无 <code>fallback_shrink</code></strong>（修订失败模式与批次大小无关，不缩批）</li></ol><p><code>revise</code> 是把语义质检/裁决产出但尚未解决的 <code>pending</code> 语义问题，交给 LLM 做定点最小修订，而不是整段重译。与 <code>correct</code> 的差别在于：<code>correct</code> 纯本地、修高频安全问题；<code>revise</code> 调 LLM、按语义问题定点修订。配置字段见 <a href="/LinguaFlow/zh/guide/translation-config-reference.html#revise">翻译配置 · 参考 · revise</a>。</p><h3 id="语义质检-semantic-qa" tabindex="-1">语义质检（<code>semantic_qa</code>） <a class="header-anchor" href="#语义质检-semantic-qa" aria-label="Permalink to &quot;语义质检（\`semantic_qa\`）&quot;">​</a></h3><p>用 LLM 扫描已译段落，捕获规则无法覆盖的语义问题（如 <code>mistranslation</code> / <code>calque</code> / <code>omission</code> / <code>addition</code> / <code>grammar</code> / <code>register</code> / <code>term_fidelity</code> / <code>naturalness</code>）：</p><ol><li>系统提示词 <strong>内置</strong>（不可改），内部已显式排除规则负责的 code，不重复报</li><li>输出为 <code>warning</code> 级问题，带 <code>span</code> 精确定位，<strong>直接进人审，不经裁决</strong></li><li>扫描范围可按 <code>segment_scope</code> 限定（<code>all</code> / <code>with_issues</code> / <code>with_issue_codes</code>），成本敏感时可只扫高价值子集</li><li>扫描失败采用<strong>软警告</strong>：写入资源 <code>warning_message</code>，作业继续而非终态失败</li></ol><div class="tip custom-block"><p class="custom-block-title">裁决、语义质检、修订的差异</p><ul><li>裁决只对已有规则问题做「保留/剔除」，不新增、不改译文</li><li>语义质检<strong>新增</strong>语义类问题</li><li>修订对段落上 <code>pending</code> 的语义问题<strong>定点改写译文</strong>、不新增问题</li></ul><p>三者互补，不冲突：语义质检把语义问题报出，修订再把 <code>pending</code> 的语义问题定点修掉。</p></div><p>协议细节见 <a href="/LinguaFlow/zh/guide/translation-config-reference.html#semantic-qa">翻译配置 · 参考 · semantic_qa</a>。审校侧呈现见 <a href="/LinguaFlow/zh/guide/review.html#质量检测">翻译审校 · 质量检测</a>。</p><hr><h2 id="ruby-注音" tabindex="-1">Ruby 注音 <a class="header-anchor" href="#ruby-注音" aria-label="Permalink to &quot;Ruby 注音&quot;">​</a></h2><p>含 <code>&lt;ruby&gt;</code> 的 HTML：</p><ol><li><strong>译前</strong> 抽出注音，正文只留 base</li><li><strong>译后</strong> 按类型过滤，把标签插回译文</li><li>本地对齐失败时，可用计划级 <strong>Ruby 重试</strong> 再调一次 LLM</li></ol><p>类型：<code>phonetic</code> / <code>semantic</code> / <code>creative</code>。字段见 <a href="/LinguaFlow/zh/guide/translation-config-reference.html#ruby-ruby">翻译配置 · 参考 · ruby</a>。</p><hr><h2 id="速率限制与重试" tabindex="-1">速率限制与重试 <a class="header-anchor" href="#速率限制与重试" aria-label="Permalink to &quot;速率限制与重试&quot;">​</a></h2><h3 id="限速" tabindex="-1">限速 <a class="header-anchor" href="#限速" aria-label="Permalink to &quot;限速&quot;">​</a></h3><p>后端 <code>rate_limit_per_minute</code>：令牌桶，超限等待而非丢弃。<code>0</code> 表示不限。</p><h3 id="超时" tabindex="-1">超时 <a class="header-anchor" href="#超时" aria-label="Permalink to &quot;超时&quot;">​</a></h3><p>后端 <code>timeout</code>（默认 60 秒）可关闭：关闭后实际请求不设时限，适合本地大模型或慢响应网关。本地超时与父上下文截止区分处理——本地超时按可重试错误退避重试，父上下文截止则跳过重试。</p><h3 id="错误策略-摘要" tabindex="-1">错误策略（摘要） <a class="header-anchor" href="#错误策略-摘要" aria-label="Permalink to &quot;错误策略（摘要）&quot;">​</a></h3><p>LLM 请求层：</p><table tabindex="0"><thead><tr><th>场景</th><th>行为</th></tr></thead><tbody><tr><td>429 / 503</td><td>退避后重试；尊重 <code>Retry-After</code>，常有最小等待</td></tr><tr><td>网络/超时</td><td>缩小批次再试（本地超时按可重试退避）</td></tr><tr><td>解析失败</td><td>先提示升级修复，再缩小批次</td></tr><tr><td>401 / 403</td><td>不重试，留给后续轮次</td></tr><tr><td>漏译段</td><td>清空该段 Target/Issues（防旧裁决跨轮复活），按本轮失败进入重试</td></tr><tr><td>部分段缺失</td><td>进入池化缩批，缺失段按更小批次重译（见 <a href="#批量与并发">批量与并发</a>）</td></tr></tbody></table><p>重试参数：<code>max_attempts</code> / <code>backoff_ms</code> / <code>jitter</code>（指数退避 + 抖动）。见 <a href="/LinguaFlow/zh/guide/translation-config-reference.html#重试-retry">翻译配置 · 参考 · 重试</a>。</p><h4 id="漏译段清空" tabindex="-1">漏译段清空 <a class="header-anchor" href="#漏译段清空" aria-label="Permalink to &quot;漏译段清空&quot;">​</a></h4><p>某翻译轮里 LLM 漏译的段落（本轮无产出）不再静默沿用数据库里的旧译文及其旧问题裁决——旧裁决跨轮复用会让上一轮已 <code>dismissed</code> 的问题「复活」。引擎会清空该段的 Target 与 Issues，按「本轮无产出 / 失败」处理进入重试。用户看到的是：漏译段被明确标记待重跑，而不是带着陈旧裁决标记的旧译文。</p><h4 id="末轮未决软警告" tabindex="-1">末轮未决软警告 <a class="header-anchor" href="#末轮未决软警告" aria-label="Permalink to &quot;末轮未决软警告&quot;">​</a></h4><p>当 <code>adjudicate</code> 或 <code>revise</code> 作为计划的最后一轮仍有未决段落时，任务不会硬失败，而是在完成提示里追加软警告：</p><ul><li><code>adjudicate</code> 末轮：提示「质量裁决未完全成功：N 个段落未能完成裁决（issue 保持待决，可重试任务或调整参数后重试）」</li><li><code>revise</code> 末轮：提示「修订未完全成功：N 个段落未能完成」</li></ul><p>多类软警告（语义质检、裁决、修订）会在完成信息里用「; 」拼接并列返回，后发生的警告不再覆盖先前的，一次看到全部未完成提示。语义质检扫描阶段的软警告另写入资源 <code>warning_message</code>，见 <a href="/LinguaFlow/zh/guide/review.html#任务级资源警告">翻译审校 · 任务级资源警告</a>。</p><h4 id="持久化层错误分类" tabindex="-1">持久化层错误分类 <a class="header-anchor" href="#持久化层错误分类" aria-label="Permalink to &quot;持久化层错误分类&quot;">​</a></h4><p>每段译文/QA 结果写回数据库时，LinguaFlow 会对底层错误分级（按数据库驱动分别识别 SQLite / PostgreSQL 的错误码），避免把可恢复的瞬时故障当成硬失败：</p><table tabindex="0"><thead><tr><th>错误性质</th><th>典型来源</th><th>行为</th></tr></thead><tbody><tr><td><strong>结构性错误</strong></td><td>schema 不匹配、字段缺失、约束违反等</td><td><strong>fail-fast</strong>，整轮中止并上报，避免后续段重复踩坑</td></tr><tr><td><strong>瞬时错误</strong></td><td>连接断开、锁竞争、临时不可写等</td><td>跳过本段写回、段保持 <code>pending</code>，<strong>留给同作业后续 translate 轮次重试</strong></td></tr><tr><td>正常写入</td><td>—</td><td>正常落库</td></tr></tbody></table><p>设计要点：</p><ul><li>每轮 <code>translate</code> 开始时重置「瞬态失败段」追踪集合；本轮瞬时失败的段不写最终译文，保留 <code>pending</code> 状态供下一轮再次取到</li><li>这意味着多轮计划里，靠后的 <code>translate</code> 轮有机会「兜住」前一轮因数据库瞬时故障漏掉的段，而不是整轮作废</li><li>该机制对用户透明：你只会在作业日志中看到部分段被标记为重试，无需手动干预</li></ul><hr><h2 id="单段预览-试译-修订" tabindex="-1">单段预览（试译 / 修订） <a class="header-anchor" href="#单段预览-试译-修订" aria-label="Permalink to &quot;单段预览（试译 / 修订）&quot;">​</a></h2><p>正式作业之外，可对单个段直接发起 <strong>预览</strong>：不创建作业、不持久化中间结果、不污染术语表/翻译记忆，在内存沙箱里跑一遍后决定是否应用。分两类：</p><ul><li><strong>试译预览</strong>：选一个执行计划，对一段<strong>原文</strong>完整跑一遍 <code>extract → translate → adjudicate → semantic_qa</code>，产出全新译文</li><li><strong>修订预览</strong>：以段落上 <code>pending</code> 的语义 issue 为修复目标，对<strong>现有译文</strong>做一次 LLM 修订（<code>revise</code>），产出定点最小修订的译文；计划须含 <code>revise</code> 轮，只有 <code>translate</code> 轮时由后端合成默认修订轮。修订结果会在内存中重跑确定性 QA 作为最终 issues，无实质改动时不返回 <code>apply_token</code></li></ul><p>二者共用如下机制：</p><ul><li><strong>诊断输出</strong>：批次事件携带 <code>round_index</code> / <code>attempt</code> / <code>system_prompt</code> / <code>user_message</code> / <code>response_format</code> / <code>json_schema</code> / <code>response_content</code>，用于排查提示词、响应格式与批次问题</li><li><strong>用量计量</strong>：调用次数与 token 消耗按预览口径统计，与正式作业区分；修订预览的唯一持久化副作用是记录真实预览用量</li><li><strong>应用译文</strong>：存在可应用结果时返回带签名的 <code>apply_token</code>（有过期时间，二者共用同一 <code>apply</code> 端点、令牌内 <code>kind</code> 区分翻译/修订）；应用时用令牌做基线（source / target / status）条件更新，检测到段落已变化会拒绝，避免覆盖他人改动</li><li><strong>内存隔离</strong>：术语表用内存 overlay、翻译记忆用 Noop，确保预览的副作用留在沙箱内</li><li><strong>并发限制</strong>：试译与修订预览共享全局并发上限，满时返回 429 并带 <code>Retry-After</code>；超时（默认 5 分钟）返回 504</li></ul><h3 id="多轮试译的过滤语义" tabindex="-1">多轮试译的过滤语义 <a class="header-anchor" href="#多轮试译的过滤语义" aria-label="Permalink to &quot;多轮试译的过滤语义&quot;">​</a></h3><p>试译支持多轮执行计划。对 <code>translate</code> 轮次，目标段是否纳入遵循如下规则：</p><table tabindex="0"><thead><tr><th>轮次位置</th><th>目标段处理</th></tr></thead><tbody><tr><td><strong>首个 <code>translate</code> 轮</strong></td><td><strong>强制翻译</strong>，无视目标段当前状态——保留「预览即重译」的语义</td></tr><tr><td><strong>后续 <code>translate</code> 轮</strong></td><td>按 <a href="/LinguaFlow/zh/guide/translation-config-reference.html#translate"><code>segment_filter</code></a> 判断：目标段状态符合过滤条件才纳入，否则<strong>跳过本轮</strong>，保留上一轮译文作为后续轮次的上下文</td></tr></tbody></table><p><code>extract</code> / <code>adjudicate</code> / <code>semantic_qa</code> 等非 translate 轮次始终处理目标段，其筛选逻辑由各自 handler 按状态自行完成，不受此规则影响。</p><p>换句话说：如果你用一个「翻译 → 裁决 → 再翻译」的计划做试译，第二个翻译轮只会处理那些状态仍满足过滤条件（如 <code>pending</code>）的目标段，避免对已经被前一轮改写的段无意义重译。</p><p>产品操作见 <a href="/LinguaFlow/zh/guide/translation-config.html#单段试译">翻译配置 · 使用 · 单段试译</a> / <a href="/LinguaFlow/zh/guide/translation-config.html#单段修订预览">单段修订预览</a>；接口契约见 <a href="/LinguaFlow/zh/guide/translation-config-reference.html#单段预览-preview">翻译配置 · 参考 · 单段预览</a>。</p><hr><h2 id="插件-规划中" tabindex="-1">插件（规划中） <a class="header-anchor" href="#插件-规划中" aria-label="Permalink to &quot;插件（规划中）&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">尚未实现</p><p>计划通过 Lua 脚本挂 <code>before_translate</code> / <code>after_translate</code> 等钩子。当前仅有接口与配置占位，请勿依赖。</p></div><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">plugins</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  enabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  scripts</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: []</span></span></code></pre></div><hr><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="/LinguaFlow/zh/guide/translation-config.html">翻译配置 · 使用</a> · <a href="/LinguaFlow/zh/guide/translation-config-reference.html">翻译配置 · 参考</a></li><li><a href="/LinguaFlow/zh/guide/review.html">翻译审校</a>（含语义质检呈现）· <a href="/LinguaFlow/zh/guide/glossary.html">术语表管理</a></li><li><a href="/LinguaFlow/zh/guide/faq.html">常见问题</a></li></ul>`,128)])])}const u=t(s,[["render",c]]);export{g as __pageData,u as default};
